{
  "name": "Pololu Maestro 多通道舵机控制器",
  "name_en": "Pololu Maestro Servo Controller",
  "manufacturer": "Pololu",
  "description": "这是一种可通过串口或 USB 控制的多通道舵机控制板，用于输出精确的 PWM/脉冲信号来驱动 RC 舵机及其他脉宽控制负载。在实验室和机器人、小车原型中，常用于转向机构、简单执行器以及灯光、制动等辅助通道控制。",
  "description_en": "This is a multi-channel servo controller board that can be controlled over serial or USB to generate precise PWM/pulse signals for RC servos and other pulse-controlled loads. In labs and robotics or vehicle prototypes, it is commonly used for steering mechanisms, simple actuators, and auxiliary channels such as lights and brake-related outputs.",
  "actions": [
    {
      "action_name": "auto-set_pulse",
      "description": "设置舵机控制脉冲宽度。",
      "description_en": "Set the servo control pulse width."
    },
    {
      "action_name": "auto-set_turn_left",
      "description": "设置左转向灯输出。",
      "description_en": "Set the left turn-signal output."
    },
    {
      "action_name": "auto-set_turn_right",
      "description": "设置右转向灯输出。",
      "description_en": "Set the right turn-signal output."
    },
    {
      "action_name": "auto-set_headlight",
      "description": "设置前照灯输出。",
      "description_en": "Set the headlight output."
    },
    {
      "action_name": "auto-set_brake",
      "description": "设置制动灯或制动相关输出。",
      "description_en": "Set the brake light or brake-related output."
    },
    {
      "action_name": "auto-readline",
      "description": "读取一行串口反馈或状态信息。",
      "description_en": "Read one line of serial feedback or status information."
    }
  ],
  "tag_hints": [
    "servo control",
    "PWM pulse generation",
    "RC steering",
    "robotics prototyping",
    "serial-controlled actuator board",
    "vehicle auxiliary outputs"
  ]
}

